import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { compilePolicy, evaluate } from './feature/src/policy.mjs';

const repository = fileURLToPath(new URL('./feature', import.meta.url));
const cli = path.join(repository, 'bin', 'gstack861.mjs');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'g861-alias-cli-'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const blob = bytes => createHash('sha1').update(Buffer.from(`blob ${bytes.length}\0`)).update(bytes).digest('hex');
const commit = JSON.parse(fs.readFileSync(path.join(repository, 'upstream.lock.json'))).gstack.commit;
console.log(JSON.stringify({ node: process.version, platform: process.platform, root, cli, sourceSha256: sha(fs.readFileSync(path.join(repository, 'src/aliases.mjs'))), fixtureOnly: true, hostDiscoveryVerified: false }));
let commands = 0;
function invoke(args, status = 0, error) {
  const r = spawnSync(process.execPath, [cli, ...args], { cwd: root, encoding: 'utf8', env: process.env });
  commands++;
  console.log(JSON.stringify({ argv: [process.execPath, cli, ...args], cwd: root, status: r.status, signal: r.signal, stdout: r.stdout, stderr: r.stderr }));
  assert.equal(r.status, status, `${args[0]} status`);
  if (error) assert.match(r.stderr, error);
  return r.stdout.trim() ? JSON.parse(r.stdout) : null;
}
function snapshot(dir) {
  const rows = [];
  function walk(base, rel = '') {
    for (const entry of fs.readdirSync(base, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const relative = path.posix.join(rel, entry.name), target = path.join(base, entry.name), stat = fs.lstatSync(target);
      if (entry.isSymbolicLink()) rows.push({ path: relative, type: 'link', target: fs.readlinkSync(target) });
      else if (entry.isDirectory()) { rows.push({ path: relative, type: 'directory' }); walk(target, relative); }
      else rows.push({ path: relative, type: 'file', sha256: sha(fs.readFileSync(target)), nlink: stat.nlink, ino: stat.ino, mode: stat.mode });
    }
  }
  walk(dir); return rows;
}
for (const host of ['zcode', 'dsh']) {
  const base = path.join(root, host), staging = path.join(base, 'canonical'), canonical = path.join(staging, 'open-gstack-browser');
  const output = path.join(base, 'aliases'), workspace = path.join(base, 'workspace'), target = path.join(workspace, `.${host}`, 'skills');
  fs.mkdirSync(path.join(canonical, 'sections', 'deep'), { recursive: true });
  const skill = Buffer.from('---\r\nname: open-gstack-browser\r\ndescription: fixture browser\r\n---\r\n# /open-gstack-browser\r\nRead sections/deep/guide.md\r\n');
  const guide = Buffer.from('canonical guide\r\n'), payload = Buffer.from([0x00, 0x01, 0xff, 0xfe, 0x64]);
  const aux = { 'sections/deep/guide.md': guide, 'payload.bin': payload };
  fs.writeFileSync(path.join(canonical, 'SKILL.md'), skill);
  for (const [key, bytes] of Object.entries(aux)) fs.writeFileSync(path.join(canonical, key), bytes);
  fs.writeFileSync(path.join(canonical, 'manifest.json'), JSON.stringify({ schemaVersion: 1, generator: 'gstack861', name: 'open-gstack-browser', host, commit, sha256: sha(skill), blob: blob(skill), files: Object.fromEntries(Object.entries(aux).map(([key, bytes]) => [key, sha(bytes)])) }));
  const original = snapshot(staging);
  const stage = invoke(['alias-stage', '--staging', staging, '--output', output, '--host', host]);
  assert.equal(stage.aliases.length, 1); assert.equal(stage.host, host);
  const alias = path.join(output, 'connect-chrome'), aliasBytes = fs.readFileSync(path.join(alias, 'SKILL.md'));
  assert.ok(aliasBytes.equals(Buffer.from(skill.toString().replace('name: open-gstack-browser', 'name: connect-chrome'))));
  assert.notEqual(fs.statSync(path.join(alias, 'SKILL.md')).ino, fs.statSync(path.join(canonical, 'SKILL.md')).ino);
  const manifest = JSON.parse(fs.readFileSync(path.join(alias, 'manifest.json')));
  assert.equal(manifest.name, 'connect-chrome'); assert.equal(manifest.aliasOf, 'open-gstack-browser');
  assert.equal(manifest.source, 'alias:open-gstack-browser'); assert.equal(manifest.status, 'generated-not-host-verified');
  assert.equal(manifest.sha256, sha(aliasBytes)); assert.equal(manifest.blob, blob(aliasBytes));
  assert.equal(manifest.host, host); assert.equal(manifest.commit, commit);
  for (const [key, bytes] of Object.entries(aux)) assert.ok(fs.readFileSync(path.join(alias, key)).equals(bytes));
  assert.deepEqual(snapshot(staging), original);

  const beforeRejection = snapshot(output);
  invoke(['alias-stage', '--staging', staging, '--output', output, '--host', host], 1, /STAGING_NOT_EMPTY/);
  assert.deepEqual(snapshot(output), beforeRejection);
  assert.deepEqual(invoke(['install', '--staging', staging, '--target', target]).installed, ['open-gstack-browser']);
  assert.deepEqual(invoke(['install', '--staging', output, '--target', target]).installed, ['connect-chrome']);
  const aliasInstalled = snapshot(path.join(target, 'connect-chrome'));
  assert.deepEqual(invoke(['install', '--staging', output, '--target', target]).skipped, ['connect-chrome']);
  assert.deepEqual(snapshot(path.join(target, 'connect-chrome')), aliasInstalled);
  const beforeDryRun = snapshot(target);
  assert.deepEqual(invoke(['install', '--staging', output, '--target', target, '--dry-run']).wouldSkip, ['connect-chrome']);
  assert.deepEqual(snapshot(target), beforeDryRun);

  const edit = path.join(target, 'connect-chrome', 'sections', 'deep', 'guide.md');
  fs.appendFileSync(edit, 'operator modification');
  const edited = snapshot(target);
  invoke(['uninstall', '--target', target], 1, /USER_FILE_REFUSED/);
  invoke(['install', '--staging', output, '--target', target], 1, /USER_FILE_REFUSED/);
  assert.deepEqual(snapshot(target), edited);
  fs.writeFileSync(edit, guide);
  fs.mkdirSync(path.join(target, 'operator-skill'));
  fs.writeFileSync(path.join(target, 'operator-skill', 'notes.txt'), 'user data survives');
  const operator = snapshot(path.join(target, 'operator-skill'));
  const preview = invoke(['uninstall', '--target', target, '--dry-run']);
  assert.deepEqual(preview.wouldUninstall.sort(), ['connect-chrome', 'open-gstack-browser']);
  assert.deepEqual(invoke(['uninstall', '--target', target]).uninstalled.sort(), ['connect-chrome', 'open-gstack-browser']);
  assert.deepEqual(snapshot(path.join(target, 'operator-skill')), operator);
  assert.deepEqual(invoke(['uninstall', '--target', target]).uninstalled, []);

  const conflict = path.join(base, 'operator-target'); fs.mkdirSync(path.join(conflict, 'connect-chrome'), { recursive: true });
  fs.writeFileSync(path.join(conflict, 'connect-chrome', 'notes.txt'), 'keep original');
  const conflictSnapshot = snapshot(conflict);
  invoke(['install', '--staging', output, '--target', conflict], 1, /USER_FILE_REFUSED/);
  assert.deepEqual(snapshot(conflict), conflictSnapshot);

  fs.appendFileSync(path.join(canonical, 'SKILL.md'), 'tamper');
  const tamperedSnapshot = snapshot(staging), tamperedOutput = path.join(base, 'tampered-output');
  invoke(['alias-stage', '--staging', staging, '--output', tamperedOutput, '--host', host], 1, /ALIAS_SOURCE_TAMPERED/);
  assert.equal(fs.existsSync(tamperedOutput), false); assert.deepEqual(snapshot(staging), tamperedSnapshot);
  fs.writeFileSync(path.join(canonical, 'SKILL.md'), skill);
  fs.appendFileSync(path.join(canonical, 'payload.bin'), 'tamper');
  invoke(['alias-stage', '--staging', staging, '--output', tamperedOutput, '--host', host], 1, /ALIAS_SOURCE_TAMPERED/);
  assert.equal(fs.existsSync(tamperedOutput), false);
  fs.writeFileSync(path.join(canonical, 'payload.bin'), payload);
  assert.deepEqual(snapshot(staging), original);

  const writeRoot = path.join(workspace, 'work'); fs.mkdirSync(writeRoot);
  const policy = compilePolicy({ schemaVersion: 1, workspace, readRoots: [workspace], writeRoots: [writeRoot], protectedRoots: [target], bindings: { [host]: { Read: { effect: 'read', pathKey: 'path' }, Write: { effect: 'write', pathKey: 'path' } } } });
  assert.equal(evaluate(policy, { host, tool: 'Write', input: { path: path.join(target, 'connect-chrome', 'SKILL.md') } }).decision, 'deny');
  assert.equal(evaluate(policy, { host, tool: 'Read', input: { path: path.join(target, '.gstack861-registry.json') } }).decision, 'abstain');
  assert.equal(evaluate(policy, { host, tool: 'Shell', input: { path: path.join(target, 'connect-chrome', 'SKILL.md') } }).decision, 'deny');
  console.log(JSON.stringify({ host, result: 'PASS', canonicalBytesPreserved: true, independentAliasIdentity: true, registryOwnedInstallUninstall: true, userFilesPreserved: true, explicitPolicyBoundary: true, hostDiscoveryVerified: false }));
}
console.log(JSON.stringify({ result: 'PASS', hosts: 2, cliCommands: commands, fixtureRootPreserved: root, actualHostProcessesStarted: 0, paidCalls: 0 }));

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { stageCommandAliases } from './feature/src/aliases.mjs';
import { installSkills } from './feature/src/install.mjs';

const root = fs.mkdtempSync(path.join(os.tmpdir(), 'g861-alias-counterexamples-'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const source = fileURLToPath(new URL('./feature/src/aliases.mjs', import.meta.url));
console.log(JSON.stringify({ node: process.version, platform: process.platform, root, source, sourceSha256: sha(fs.readFileSync(source)) }));
let failures = 0;
function fixture(name, bytes = Buffer.from('---\nname: open-gstack-browser\ndescription: browser\n---\n# canonical body\n')) {
  const base = path.join(root, name), staging = path.join(base, 'staging'), dir = path.join(staging, 'open-gstack-browser');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'SKILL.md'), bytes);
  const manifest = { schemaVersion: 1, generator: 'gstack861', name: 'open-gstack-browser', host: 'zcode', commit: 'a'.repeat(40), sha256: sha(bytes), files: {} };
  fs.writeFileSync(path.join(dir, 'manifest.json'), JSON.stringify(manifest));
  return { base, staging, dir, manifest, output: path.join(base, 'output') };
}
function save(f) { fs.writeFileSync(path.join(f.dir, 'manifest.json'), JSON.stringify(f.manifest)); }
function check(name, body) {
  try { body(); console.log(JSON.stringify({ name, expectedSafetyAssertion: 'PASS' })); }
  catch (error) { failures++; console.log(JSON.stringify({ name, expectedSafetyAssertion: 'FAIL', message: error.message })); }
}
check('output ancestor symlink must not write inside the canonical staging', () => {
  const f = fixture('physical-overlap');
  const link = path.join(f.base, 'parent-link'); fs.symlinkSync(f.staging, link, 'dir');
  const output = path.join(link, 'nested');
  let error; try { stageCommandAliases({ staging: f.staging, output, host: 'zcode' }); } catch (e) { error = e; }
  console.log(JSON.stringify({ observed: 'physical-overlap', error: error?.message ?? null, unexpectedSourceTreeWrite: fs.existsSync(path.join(f.staging, 'nested', 'connect-chrome', 'SKILL.md')) }));
  assert.ok(error, 'alias-stage accepted an output which resolves inside canonical staging');
  assert.equal(fs.existsSync(path.join(f.staging, 'nested')), false);
});
check('only name bytes may change in a CRLF skill', () => {
  const original = Buffer.from('---\r\nname: open-gstack-browser\r\ndescription: browser\r\n---\r\n# body\r\n');
  const f = fixture('crlf', original); stageCommandAliases({ staging: f.staging, output: f.output, host: 'zcode' });
  const actual = fs.readFileSync(path.join(f.output, 'connect-chrome', 'SKILL.md'));
  const expected = Buffer.from(original.toString().replace('name: open-gstack-browser', 'name: connect-chrome'));
  console.log(JSON.stringify({ observed: 'crlf', originalSha256: sha(original), expectedSha256: sha(expected), actualSha256: sha(actual), canonicalUnchanged: fs.readFileSync(path.join(f.dir, 'SKILL.md')).equals(original) }));
  assert.ok(actual.equals(expected), 'alias-stage rewrote CRLF bytes outside the frontmatter name');
});
check('only name bytes may change in a skill with non-UTF8 body bytes', () => {
  const original = Buffer.concat([Buffer.from('---\nname: open-gstack-browser\n---\n'), Buffer.from([0x61, 0xff, 0xc0, 0x62])]);
  const f = fixture('body-bytes', original); stageCommandAliases({ staging: f.staging, output: f.output, host: 'zcode' });
  const actual = fs.readFileSync(path.join(f.output, 'connect-chrome', 'SKILL.md'));
  const expected = Buffer.concat([Buffer.from('---\nname: connect-chrome\n---\n'), Buffer.from([0x61, 0xff, 0xc0, 0x62])]);
  console.log(JSON.stringify({ observed: 'body-bytes', expectedSha256: sha(expected), actualSha256: sha(actual), canonicalUnchanged: fs.readFileSync(path.join(f.dir, 'SKILL.md')).equals(original) }));
  assert.ok(actual.equals(expected), 'alias-stage silently replaced verified non-UTF8 body bytes');
});
check('case-colliding auxiliary paths must be rejected before output exists', () => {
  const f = fixture('case-collision');
  for (const key of ['Guide.md', 'guide.md']) { fs.writeFileSync(path.join(f.dir, key), key); f.manifest.files[key] = sha(Buffer.from(key)); } save(f);
  let error; try { stageCommandAliases({ staging: f.staging, output: f.output, host: 'zcode' }); } catch (e) { error = e; }
  let installError; try { installSkills({ staging: f.output, target: path.join(f.base, 'target'), dryRun: true }); } catch (e) { installError = e; }
  console.log(JSON.stringify({ observed: 'case-collision', aliasError: error?.message ?? null, installError: installError?.message ?? null, outputExists: fs.existsSync(f.output) }));
  assert.ok(error, 'alias-stage created auxiliary paths which the installer rejects');
  assert.equal(fs.existsSync(f.output), false);
});
check('invalid commit type must be rejected rather than staged as an unusable alias', () => {
  const f = fixture('commit-type'); f.manifest.commit = ['a'.repeat(40)]; save(f);
  let error; try { stageCommandAliases({ staging: f.staging, output: f.output, host: 'zcode' }); } catch (e) { error = e; }
  let installError; try { installSkills({ staging: f.output, target: path.join(f.base, 'target'), dryRun: true }); } catch (e) { installError = e; }
  console.log(JSON.stringify({ observed: 'commit-type', aliasError: error?.message ?? null, installError: installError?.message ?? null }));
  assert.ok(error, 'alias-stage accepted an array commit that the installer rejects');
