check('reserved auxiliary name must fail before deleting an existing operator output directory', () => {
  const f = fixture('reserved-file'); f.manifest.files['SKILL.md'] = f.manifest.sha256; save(f); fs.mkdirSync(f.output);
  const before = fs.statSync(f.output);
  let error; try { stageCommandAliases({ staging: f.staging, output: f.output, host: 'zcode' }); } catch (e) { error = e; }
  console.log(JSON.stringify({ observed: 'reserved-file', error: error?.message ?? null, outputPreserved: fs.existsSync(f.output) }));
  assert.ok(error);
  assert.ok(fs.existsSync(f.output), 'alias-stage deleted a pre-existing operator-owned output directory');
  assert.equal(fs.statSync(f.output).ino, before.ino);
});
console.log(JSON.stringify({ cases: 6, failures, fixtureRootPreserved: root }));
process.exitCode = failures ? 1 : 0;

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { stageCommandAliases } from './feature/src/aliases.mjs';

const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'g861-alias-yaml-keys-'));
const source = fileURLToPath(new URL('./feature/src/aliases.mjs', import.meta.url));
console.log(JSON.stringify({ node: process.version, uid: process.getuid?.(), platform: process.platform,
  source, sourceSha256: sha(fs.readFileSync(source)), root, scope: 'Real staging API only; no host, parser substitution or file-tool execution.' }));
const cases = [
  ['tag-shorthand', '!!str name: other'],
  ['tag-verbatim', '!<tag:yaml.org,2002:str> name: other'],
  ['anchor-key', '&anchor name: other'],
  ['alias-key', 'identity: &nameKey name\n*nameKey : other'],
];
let failures = 0;
for (const [name, header] of cases) {
  const base = path.join(root, name), staging = path.join(base, 'staging');
  const dir = path.join(staging, 'open-gstack-browser'), output = path.join(base, 'output');
  fs.mkdirSync(dir, { recursive: true });
  const bytes = Buffer.from(`---\nname: open-gstack-browser\n${header}\n---\ncanonical body\n`);
  const manifestBytes = Buffer.from(JSON.stringify({ schemaVersion: 1, generator: 'gstack861',
    name: 'open-gstack-browser', host: 'zcode', commit: 'a'.repeat(40), sha256: sha(bytes), files: {} }));
  fs.writeFileSync(path.join(dir, 'SKILL.md'), bytes);
  fs.writeFileSync(path.join(dir, 'manifest.json'), manifestBytes);
  let error;
  try { stageCommandAliases({ staging, output, host: 'zcode' }); } catch (e) { error = e; }
  const generated = path.join(output, 'connect-chrome', 'SKILL.md');
  const aliasBytes = fs.existsSync(generated) ? fs.readFileSync(generated) : null;
  const canonicalUnchanged = fs.readFileSync(path.join(dir, 'SKILL.md')).equals(bytes);
  const manifestUnchanged = fs.readFileSync(path.join(dir, 'manifest.json')).equals(manifestBytes);
  const result = { name, header, error: error?.message ?? null, outputExists: fs.existsSync(output),
    canonicalSha256: sha(bytes), manifestSha256: sha(manifestBytes), canonicalUnchanged, manifestUnchanged,
    generated: aliasBytes && { path: generated, sha256: sha(aliasBytes), text: aliasBytes.toString() } };
  try {
    assert.match(error?.message ?? '', /^ALIAS_FRONTMATTER_INVALID$/);
    assert.equal(fs.existsSync(output), false);
    assert.equal(canonicalUnchanged, true);
    assert.equal(manifestUnchanged, true);
    result.safetyAssertion = 'PASS';
  } catch (e) { failures++; result.safetyAssertion = 'FAIL'; result.message = e.message; }
  console.log(JSON.stringify(result));
}
console.log(JSON.stringify({ cases: cases.length, passed: cases.length - failures, failures,
  fixtureRootPreserved: root, actualHostProcesses: 0 }));
process.exitCode = failures ? 1 : 0;

import assert from 'node:assert/strict';
import fs from 'node:fs';
