import * as skillsAdapter from './feature/src/adapters/dsh-skills.mjs';

const task = fileURLToPath(new URL('.', import.meta.url)), repo = path.join(task, 'feature');
const root = path.join(task, 'evidence', 'dsh-offline-fixture');
const workspace = path.join(root, 'workspace'), staging = path.join(root, 'staging');
