fs.mkdirSync(root); fs.mkdirSync(workspace); fs.mkdirSync(profiles, { recursive: true });
const installedBodies = {
  'gstack': '---\nname: gstack\ndescription: Route local review work.\n---\nRead the chosen skill before acting.\n',
  'gstack-review': '---\nname: gstack-review\ndescription: Review local changes.\n---\nInspect the local diff.\n',
};
for (const [name, body] of Object.entries(installedBodies)) {
  const dir = path.join(staging, name); fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'SKILL.md'), body);
  fs.writeFileSync(path.join(dir, 'manifest.json'), JSON.stringify({ schemaVersion: 1, name, host: 'dsh',
    generator: 'gstack861', commit: 'a'.repeat(40), sha256: sha(body), status: 'generated-not-host-verified' }));
}
const installed = installSkills({ staging, target: skillsDir });
assert.deepEqual(installed.installed, Object.keys(installedBodies).sort());
const policy = { schemaVersion: 1, workspace, readRoots: [workspace], writeRoots: [workspace], protectedRoots: [],
  bindings: { zcode: {}, dsh: { read: { effect: 'read', pathKey: 'file_path' }, write: { effect: 'write', pathKey: 'file_path' } } } };
const policyBytes = JSON.stringify(policy, null, 2) + '\n';
fs.writeFileSync(policyPath, policyBytes, { mode: 0o600 });
const operator = path.join(root, 'operator-owned.txt'); fs.writeFileSync(operator, 'must remain unchanged\n');
const originalOperatorHash = sha(fs.readFileSync(operator));
const argv = [path.join(repo, 'bin/gstack861.mjs'), 'dsh-profile-stage', '--output', output,
  '--policy', policyPath, '--adapter', adapterPath, '--skills', skillsDir];
const child = spawnSync(process.execPath, argv, { cwd: workspace, encoding: 'utf8',
  env: { ...process.env, DSH_HOME: home, DSH_AGENTS_HOME: path.join(root, 'isolated-agents'), DSH_TELEMETRY_DISABLED: '1' } });
console.log(JSON.stringify({ kind: 'actual-cli', argv: [process.execPath, ...argv], exitCode: child.status, stdout: child.stdout, stderr: child.stderr }));
assert.equal(child.status, 0); const result = JSON.parse(child.stdout);
assert.equal(result.status, 'scaffolded-not-host-verified');
const patch = fs.readFileSync(path.join(output, 'cordis.patch.yml'), 'utf8');
const ids = [...patch.matchAll(/^    - id: (.+)$/gm)].map(v => v[1]);
assert.deepEqual(ids, ['system-prompt', 'tools', 'gstack861-guard', 'gstack861-skills']);
assert.ok(patch.includes('policyPath: ' + JSON.stringify(policyPath)));
assert.ok(patch.includes('skillsDir: ' + JSON.stringify(skillsDir)));
const packageJson = JSON.parse(fs.readFileSync(path.join(output, 'package.json')));
assert.deepEqual(packageJson.dsh.profile.bundles, []);
const loaded = {}, pluginEvidence = [];
for (const [name, spec] of Object.entries(packageJson.dependencies)) {
  assert.match(spec, /^file:/);
  const dir = path.resolve(output, spec.slice(5)), pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json')));
  loaded[name] = await import(pathToFileURL(path.join(dir, pkg.main)).href);
  const expected = name === 'gstack861-guard' ? guardAdapter : skillsAdapter;
  assert.equal(loaded[name].apply, expected.apply);
  assert.deepEqual(loaded[name].inject, expected.inject);
  pluginEvidence.push({ name, localDependency: spec, inject: loaded[name].inject, identityMatchesProjectAdapter: true,
    shim: fs.readFileSync(path.join(dir, pkg.main), 'utf8') });
}
assert.deepEqual(Object.keys(loaded).sort(), ['gstack861-guard', 'gstack861-skills']);
let guard; const sections = []; const dispose = () => {};
assert.equal(loaded['gstack861-guard'].apply({ tools: { guard(fn) { guard = fn; return dispose; } } }, { policyPath }), dispose);
const admissions = [
  ['in-workspace write', { name: 'write', arguments: { file_path: path.join(workspace, 'allowed.txt') } }, undefined],
  ['outside write', { name: 'write', arguments: { file_path: operator } }, 'gstack861:OUTSIDE_SCOPE'],
  ['unmapped tool', { name: 'exec', arguments: { command: 'unused' } }, 'gstack861:UNMAPPED_TOOL'],
  ['cancelled call', { name: 'write', arguments: { file_path: path.join(workspace, 'allowed.txt') }, signal: { aborted: true } }, 'gstack861:CANCELLED'],
].map(([label, call, expected]) => { const actual = guard(call); assert.equal(actual, expected); return { label, result: actual ?? 'abstain' }; });
const ctx = { systemPrompt: { section(value) { sections.push(value); return dispose; } } };
assert.equal(loaded['gstack861-skills'].apply(ctx, { skillsDir }), dispose);
assert.equal(sections.length, 1); assert.equal(sections[0].interpolate, false);
for (const name of Object.keys(installedBodies)) assert.ok(sections[0].text.includes(path.join(skillsDir, name, 'SKILL.md')));
