import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { stageDshProfile } from './feature/src/dsh-profile.mjs';
import { apply as guardApply } from './feature/src/adapters/dsh.mjs';

const root = fileURLToPath(new URL('.', import.meta.url));
const label = process.argv[2];
assert.match(label, /^[a-z0-9-]+$/);
const fixtures = path.join(root, 'evidence', `dsh-${label}-fixtures`);
fs.mkdirSync(fixtures, { recursive: false });
const adapter = path.join(root, 'feature', 'src', 'adapters', 'dsh.mjs');
const source = path.join(root, 'feature', 'src', 'dsh-profile.mjs');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
console.log(JSON.stringify({ kind: 'scope', mode: 'offline-isolated-fixture', hostActivation: 'NOT_RUN', platform: process.platform,
  node: process.version, source, sourceSha256: sha(fs.readFileSync(source)), adapter,
  adapterSha256: sha(fs.readFileSync(adapter)), fixtures }));

function fixture(name) {
  const dir = path.join(fixtures, name), workspace = path.join(dir, 'workspace');
  const outside = path.join(dir, 'private'), skills = path.join(workspace, '.dsh', 'skills');
  fs.mkdirSync(skills, { recursive: true }); fs.mkdirSync(outside);
  const policy = path.join(outside, 'policy.json');
  fs.writeFileSync(policy, JSON.stringify({ schemaVersion: 1, workspace, readRoots: [workspace], writeRoots: [], protectedRoots: [], bindings: { dsh: {}, zcode: {} } }), { mode: 0o600 });
  return { dir, workspace, policy, skills, adapter, output: path.join(dir, 'profile') };
}
const options = f => ({ output: f.output, policyPath: f.policy, adapterPath: f.adapter, skillsDir: f.skills });
function inventory(output) {
  if (!fs.existsSync(output)) return [];
  return fs.readdirSync(output, { recursive: true, withFileTypes: true }).filter(v => v.isFile()).map(v => {
    const file = path.join(v.parentPath, v.name), bytes = fs.readFileSync(file);
    return { path: path.relative(output, file).split(path.sep).join('/'), bytes: bytes.length, sha256: sha(bytes) };
  }).sort((a,b) => a.path.localeCompare(b.path));
}
const checks = [];
async function check(name, run) {
  try { await run(); checks.push({ name, pass: true }); }
  catch (e) { checks.push({ name, pass: false, error: e.message, code: e.code }); }
}

await check('both declared local plugin packages exist and import the real adapters', async () => {
  const f = fixture('dependencies'), result = stageDshProfile(options(f));
  console.log(JSON.stringify({ kind: 'generated-profile', result, inventory: inventory(f.output) }));
  const pkg = JSON.parse(fs.readFileSync(path.join(f.output, 'package.json')));
  for (const [name, spec] of Object.entries(pkg.dependencies)) {
    assert.match(spec, /^file:/);
    const packageDir = path.resolve(f.output, spec.slice(5)), manifestFile = path.join(packageDir, 'package.json');
    assert.equal(fs.existsSync(manifestFile), true, `missing declared plugin ${name}: ${manifestFile}`);
    const manifest = JSON.parse(fs.readFileSync(manifestFile));
    assert.equal(manifest.name, name);
    const loaded = await import(pathToFileURL(path.join(packageDir, manifest.main)).href);
    assert.equal(loaded.name, name); assert.equal(typeof loaded.apply, 'function');
  }
});

await check('policy rejected by real guard is refused before generating a scaffold', () => {
  const f = fixture('invalid-policy');
  fs.writeFileSync(f.policy, JSON.stringify({ schemaVersion: 1, workspace: f.workspace }));
  let activationError;
  try { guardApply({ tools: { guard() { throw Error('must not register an invalid policy'); } } }, { policyPath: f.policy }); }
  catch (e) { activationError = e.message; }
  assert.equal(activationError, 'ROOT_ARRAY_REQUIRED');
  let stageError, result;
  try { result = stageDshProfile(options(f)); } catch (e) { stageError = e.message; }
  console.log(JSON.stringify({ kind: 'policy-mismatch', activationError, stageError, result, inventory: inventory(f.output) }));
  assert.ok(stageError, 'scaffold reported success even though real guard rejects policy');
  assert.equal(fs.existsSync(f.output), false);
});

for (const field of ['output', 'policy', 'adapter', 'skills']) {
  await check(`refuse ancestor directory symlink for ${field} before profile output`, () => {
    const f = fixture(`ancestor-${field}`), real = path.join(f.dir, 'real'), alias = path.join(f.dir, 'alias');
    fs.mkdirSync(path.join(real, 'nested'), { recursive: true });
    fs.symlinkSync(real, alias, 'dir');
    if (field === 'output') f.output = path.join(alias, 'nested', 'profile');
    if (field === 'policy') { fs.copyFileSync(f.policy, path.join(real, 'nested', 'policy.json')); f.policy = path.join(alias, 'nested', 'policy.json'); }
    if (field === 'adapter') { fs.copyFileSync(f.adapter, path.join(real, 'nested', 'dsh.mjs')); f.adapter = path.join(alias, 'nested', 'dsh.mjs'); }
    if (field === 'skills') { fs.mkdirSync(path.join(real, 'nested', 'skills')); f.skills = path.join(alias, 'nested', 'skills'); }
    let stageError, result;
    try { result = stageDshProfile(options(f)); } catch (e) { stageError = e.message; }
    console.log(JSON.stringify({ kind: 'ancestor-link', field, stageError, result, actualOutput: fs.existsSync(f.output) ? fs.realpathSync(f.output) : null,
      inventory: inventory(f.output) }));
    assert.ok(stageError, `accepted ${field} via an ancestor symlink`);
    assert.equal(fs.existsSync(f.output), false);
  });
}
