test('successful rename followed by one readback EIO rolls back both files', t => {
 const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'g861-zcode-eio-')));
 t.after(()=>fs.rmSync(root,{recursive:true,force:true}));
 const zdir=path.join(root,'.zcode');fs.mkdirSync(zdir);
 const file=path.join(zdir,'config.json'),receipt=path.join(zdir,'.gstack861-zcode-config.json');
