 const plan=planZcodeConfig(input),original=fs.openSync;let injected=0;
 t.mock.method(fs,'openSync',(target,flags,...args)=>{
  if(target===file&&typeof flags==='number'&&fs.existsSync(file)&&injected===0){injected++;const error=new Error('INJECTED_READBACK_EIO');error.code='EIO';throw error;}
  return original(target,flags,...args);
 });
 assert.throws(()=>applyZcodeConfigPlan(plan),/ZCODE_CONFIG_UNSAFE/);
